int main(void)
{
    int n, i, k;
    long long c, mx = 0;

    if (scanf("%d", &n) != 1)
        return 0;

    if (n < 1 || n > 30) {
        printf("INVALID\n");
        return 0;
    }

    for (i = 0; i < n; i++) {
        c = 1;                       /* 每行第一个系数恒为 1 */
        for (k = 0; k <= i; k++) {
            if (k > 0)
                putchar(' ');
            printf("%lld", c);
            if (c > mx)
                mx = c;
            /* C(i, k+1) = C(i, k) * (i - k) / (k + 1)，每一步都精确整除 */
            c = c * (i - k) / (k + 1);
        }
        putchar('\n');
    }

    printf("max: %lld\n", mx);
    return 0;
}

