#include <stdio.h>

enum { NORMAL, WORD, STRING, ESCAPE };

static int is_alpha(int ch)
{
    return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
}

int main(void)
{
    int state = NORMAL;
    int words = 0, strings = 0;
    int ch;

    while ((ch = getchar()) != EOF && ch != '\n') {
        /* 单词遇到非字母时先结束单词，同一个字符要按新状态再判一次 */
        while (state == WORD && !is_alpha(ch))
            state = NORMAL;

        switch (state) {
        case NORMAL:
            if (ch == '"')
                state = STRING;
            else if (is_alpha(ch)) {
                state = WORD;
                words++;
            }
            break;
        case WORD:
            break;                  /* 仍是字母，继续当前单词 */
        case STRING:
            if (ch == '\\')
                state = ESCAPE;
            else if (ch == '"') {
                state = NORMAL;
                strings++;
            }
            break;
        default:                    /* ESCAPE：被转义的字符不改变字符串边界 */
            state = STRING;
            break;
        }
    }

    printf("words: %d\n", words);
    printf("strings: %d\n", strings);
    printf("unclosed: %d\n", (state == STRING || state == ESCAPE) ? 1 : 0);
    return 0;
}

