#include <stdio.h>

static long long gcd(long long a, long long b)
{
    /* 循环不变式：gcd(a, b) 的值在整个循环中不变 */
    while (b != 0) {
        long long t = a % b;
        a = b;
        b = t;
    }
    return a;
}

int main(void)
{
    int n, i;
    long long g = 0, l = 1, x;

    if (scanf("%d", &n) != 1 || n < 1)
        return 0;

    for (i = 0; i < n; i++) {
        if (scanf("%lld", &x) != 1)
            return 0;
        g = gcd(g, x);               /* gcd(0, x) 就是 x，正好作为初值 */
        l = l / gcd(l, x) * x;       /* 先除后乘，避免中间结果溢出 */
    }

    printf("gcd: %lld\n", g);
    printf("lcm: %lld\n", l);
    return 0;
}

