{
    long long n, l, a, rest;
    int count = 0;
    long long bestA = 0, bestL = 0;

    if (scanf("%lld", &n) != 1)
        return 0;

    /* 枚举项数 L：L*(L-1)/2 < n 保证首项至少为 1 */
    for (l = 2; l * (l - 1) / 2 < n; l++) {
        rest = n - l * (l - 1) / 2;
        if (rest % l != 0)
            continue;                 /* 首项不是整数，跳过 */
        a = rest / l;
        if (a < 1)
            continue;
        count++;
        if (bestA == 0 || a < bestA) {
            bestA = a;
            bestL = l;
        }
    }

    printf("count: %d\n", count);
    if (count == 0)
        printf("first: none\n");
    else
        printf("first: %lld %lld\n", bestA, bestL);
    return 0;
}

