#include <stdio.h>

int main(void)
{
    long long n;
    int b, len = 0, i, pal = 1;
    char buf[70];
    const char *digits = "0123456789ABCDEF";

    if (scanf("%lld %d", &n, &b) != 2)
        return 0;
    if (b < 2 || b > 16)
        return 0;

    /* 短除法：最低位先进入缓冲区，所以缓冲区里是反序的数字 */
    if (n == 0)
        buf[len++] = '0';
    while (n > 0) {
        buf[len++] = digits[n % b];
        n /= b;
    }

    /* 在反序缓冲区上判断回文与正序判断等价 */
    for (i = 0; i < len / 2; i++) {
        if (buf[i] != buf[len - 1 - i]) {
            pal = 0;
            break;
        }
    }

    printf("base: ");
    for (i = len - 1; i >= 0; i--)
        putchar(buf[i]);
    putchar('\n');

    printf("len: %d\n", len);
    printf("palindrome: %s\n", pal ? "yes" : "no");
    return 0;
}

