#include <stdio.h>

static int is_leap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

static int month_days(int y, int m)
{
    static const int days[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    if (m == 2 && is_leap(y))
        return 29;
    return days[m];
}

static void next_day(int *y, int *m, int *d)
{
    if (*d < month_days(*y, *m)) {
        (*d)++;
    } else {
        *d = 1;
        if (*m < 12) {
            (*m)++;
        } else {
            *m = 1;
            (*y)++;
        }
    }
}

int main(void)
{
    int y, m, d;
    long long k;

    if (scanf("%d %d %d %lld", &y, &m, &d, &k) != 4)
        return 0;

    /* 阶段一：逐日推进到 1 月 1 日，最多 365 步 */
    while (k > 0 && (m != 1 || d != 1)) {
        next_day(&y, &m, &d);
        k--;
    }

    /* 阶段二：此时一定是 1 月 1 日，整年跳跃才是安全的 */
    while (k >= (long long)(is_leap(y) ? 366 : 365)) {
        k -= is_leap(y) ? 366 : 365;
        y++;
    }

    /* 阶段三：剩余不足一年，逐日推进 */
    while (k > 0) {
        next_day(&y, &m, &d);
        k--;
    }

    printf("%04d-%02d-%02d\n", y, m, d);
    return 0;
}

