#include <iostream>
#include <iomanip>
using namespace std;

static bool isLeap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || y % 400 == 0;
}

static int monthDays(int y, int m)
{
    static const int days[13] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    if (m == 2 && isLeap(y))
        return 29;
    return days[m];
}

static void nextDay(int &y, int &m, int &d)
{
    if (d < monthDays(y, m)) {
        ++d;
    } else {
        d = 1;
        if (m < 12) {
            ++m;
        } else {
            m = 1;
            ++y;
        }
    }
}

int main()
{
    int y, m, d;
    long long k;
    if (!(cin >> y >> m >> d >> k))
        return 0;

    // 阶段一：逐日推进到 1 月 1 日
    while (k > 0 && (m != 1 || d != 1)) {
        nextDay(y, m, d);
        --k;
    }

    // 阶段二：从 1 月 1 日出发做整年跳跃
    while (k >= (isLeap(y) ? 366LL : 365LL)) {
        k -= isLeap(y) ? 366LL : 365LL;
        ++y;
