import sys

def is_leap(y):
    return (y % 4 == 0 and y % 100 != 0) or y % 400 == 0

def month_days(y, m):
    days = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if m == 2 and is_leap(y):
        return 29
    return days[m]

def next_day(y, m, d):
    # 返回后一天的 (y, m, d)
    if d < month_days(y, m):
        return y, m, d + 1
    if m < 12:
        return y, m + 1, 1
    return y + 1, 1, 1

def main():
    data = sys.stdin.read().split()
    if len(data) < 4:
        return

    y, m, d, k = (int(v) for v in data[:4])

    # 阶段一：逐日推进到 1 月 1 日
    while k > 0 and (m != 1 or d != 1):
        y, m, d = next_day(y, m, d)
        k -= 1

    # 阶段二：从 1 月 1 日出发做整年跳跃
    while k >= (366 if is_leap(y) else 365):
        k -= 366 if is_leap(y) else 365
        y += 1

    # 阶段三：剩余不足一年，逐日推进
    while k > 0:
        y, m, d = next_day(y, m, d)
        k -= 1

    print(f"{y:04d}-{m:02d}-{d:02d}")

if __name__ == "__main__":
    main()

