    for (i = 2; i <= n; i++) {
        if (scanf("%d", &x) != 1)
            return 0;
        /* 条件表达式 + 逗号表达式：严格更大时同时更新值与首次位置 */
        mx = (x > mx) ? (mxp = i, x) : mx;
        mn = (x < mn) ? x : mn;
        pos += (x > 0) ? 1 : 0;
        even += (x % 2 == 0) ? 1 : 0;
    }

    printf("max: %d at %d\n", mx, mxp);
    printf("min: %d\n", mn);
    printf("pos: %d\n", pos);
    printf("even: %d\n", even);
    return 0;
}

