int main(void)
{
    long long n, x, peak, steps = 0, peakStep = 0, oddCnt = 0;

    if (scanf("%lld", &n) != 1 || n < 1)
        return 0;

    x = n;
    peak = x;                        /* 起点记为第 0 步 */
    while (x != 1) {
        if (x % 2 == 0) {
            x /= 2;
        } else {
            oddCnt++;                /* 当前这个奇数计入统计，最后的 1 不计 */
            x = 3 * x + 1;
        }
        steps++;
        if (x > peak) {
            peak = x;
            peakStep = steps;
        }
    }

    printf("steps: %lld\n", steps);
    printf("peak: %lld at %lld\n", peak, peakStep);
    printf("odd: %lld\n", oddCnt);
    return 0;
}

